/** Actual controller packets/native screen/rendering and player save/rejoin. Materials are fixture setup. */
@Mod.EventBusSubscriber(modid="jdte",value=Dist.CLIENT)
public final class TimeMultitoolClientSmoke {
    private static final BlockPos FIRST=new BlockPos(34,111,32),SECOND=FIRST.east(),THIRD=SECOND.east();
    private static int stage,ticks,at,guiPhase;private static volatile boolean done;private static volatile RuntimeException failure;private static volatile net.minecraft.nbt.CompoundTag expected;private static boolean disconnecting;
    private static void check(boolean b,String s){if(!b)throw new IllegalStateException("Time Multitool client stage "+stage+": "+s);}
    private static void next(){stage++;at=ticks;com.mojang.logging.LogUtils.getLogger().info("Time Multitool graphical stage {}",stage);}
    private static void server(Minecraft mc,java.util.function.Consumer<ServerPlayer> action){var server=mc.getSingleplayerServer();var id=mc.player.getUUID();server.execute(()->{try{action.accept(server.getPlayerList().getPlayer(id));}catch(RuntimeException x){failure=x;throw x;}});}
    private static int fe(ItemStack s){return s.getCapability(ForgeCapabilities.ENERGY).orElseThrow(IllegalStateException::new).getEnergyStored();}
    private static void resource(ItemStack s,int energy,int fluid){check(fe(s)==energy&&FluidContainingItem.getAvailableFluid(s)==fluid,"exact synchronized resources "+fe(s)+"/"+FluidContainingItem.getAvailableFluid(s)+" expected "+energy+"/"+fluid);}
    private static void shot(Minecraft mc,String name){Screenshot.grab(mc.gameDirectory,name,mc.getMainRenderTarget(),x->{});}
    private static void shift(Minecraft mc,boolean down){mc.options.keyShift.setDown(down);mc.player.setShiftKeyDown(down);mc.player.connection.send(new ServerboundPlayerCommandPacket(mc.player,down?ServerboundPlayerCommandPacket.Action.PRESS_SHIFT_KEY:ServerboundPlayerCommandPacket.Action.RELEASE_SHIFT_KEY));}
    private static void release(Minecraft mc){mc.options.keyAttack.setDown(false);MinecraftForge.EVENT_BUS.post(new InputEvent.MouseButton.Post(0,0,0));mc.gameMode.stopDestroyBlock();}
    private static InputEvent.InteractionKeyMappingTriggered attack(Minecraft mc,BlockPos pos){mc.hitResult=new BlockHitResult(Vec3.atCenterOf(pos),Direction.WEST,pos,false);var event=new InputEvent.InteractionKeyMappingTriggered(0,mc.options.keyAttack,InteractionHand.MAIN_HAND);MinecraftForge.EVENT_BUS.post(event);return event;}
    private static void mine(Minecraft mc,BlockPos pos){check(mc.gameMode.startDestroyBlock(pos,Direction.WEST),"real controller accepts block attack");}
    @SubscribeEvent public static void tick(TickEvent.ClientTickEvent e)throws Exception{
        if(e.phase!=TickEvent.Phase.END||!Boolean.getBoolean("jdte.multitoolSmoke")||disconnecting)return;if(failure!=null)throw failure;var mc=Minecraft.getInstance();int elapsed=++ticks-at;check(ticks<5000,"timeout");
        if(stage==20&&mc.player==null&&mc.getSingleplayerServer()==null&&elapsed>40){mc.createWorldOpenFlows().loadLevel(new net.minecraft.client.gui.screens.TitleScreen(),"jdte-mineral-client-smoke");next();return;}if(mc.player==null||mc.level==null||mc.getSingleplayerServer()==null)return;
        switch(stage){
            case 0->{if(mc.player.tickCount<70)return;server(mc,p->{var l=p.serverLevel();for(var b:BlockPos.betweenClosed(FIRST.offset(-5,-2,-4),THIRD.offset(4,3,4))){l.removeBlockEntity(b);l.setBlockAndUpdate(b,b.getY()==109?Blocks.STONE.defaultBlockState():Blocks.AIR.defaultBlockState());}p.gameMode.changeGameModeForPlayer(net.minecraft.world.level.GameType.SURVIVAL);p.getInventory().clearContent();p.getInventory().selected=0;var s=new ItemStack(JDTEItems.TIME_MULTITOOL.get());s.setHoverName(net.minecraft.network.chat.Component.literal("Time Multitool - retained mode"));s.getOrCreateTag().putString("unknown_fixture_tag","preserved");s.getCapability(ForgeCapabilities.ENERGY).orElseThrow(IllegalStateException::new).receiveEnergy(5000,false);s.getCapability(ForgeCapabilities.FLUID_HANDLER_ITEM).orElseThrow(IllegalStateException::new).fill(new FluidStack(com.direwolf20.justdirethings.setup.Registration.TIME_FLUID_SOURCE.get(),10000),IFluidHandler.FluidAction.EXECUTE);p.setItemInHand(InteractionHand.MAIN_HAND,s);for(var b:java.util.List.of(FIRST,SECOND,THIRD))l.setBlockAndUpdate(b,Blocks.STONE.defaultBlockState());p.teleportTo(32.5,110,32.5);p.setYRot(0);p.setXRot(0);p.inventoryMenu.broadcastChanges();done=true;});next();}
            case 1->{if(!done||elapsed<30)return;check(TimeMultitoolItem.getSelectedSpeedMode(mc.player.getMainHandItem())==TimeMultitoolSpeedMode.ONE,"source default1x");shift(mc,true);for(int i=0;i<3;i++)mc.gameMode.useItem(mc.player,InteractionHand.MAIN_HAND);shift(mc,false);next();}
            case 2->{if(elapsed<30)return;check(TimeMultitoolItem.getSelectedSpeedMode(mc.player.getMainHandItem())==TimeMultitoolSpeedMode.SIXTEEN,"three actual sneak-use C2S actions synchronize16x");resource(mc.player.getMainHandItem(),5000,10000);check(mc.screen==null&&mc.isWindowActive(),"active real window for input gate");mc.options.keyAttack.setDown(true);MinecraftForge.EVENT_BUS.post(new InputEvent.MouseButton.Post(0,1,0));check(!attack(mc,FIRST).isCanceled(),"first pressed target allowed");mine(mc,FIRST);check(attack(mc,SECOND).isCanceled(),"same-press target switch below250ms blocked before packet");next();}
            case 3->{if(elapsed<25)return;check(mc.level.getBlockState(FIRST).isAir()&&mc.level.getBlockState(SECOND).is(Blocks.STONE),"first actual attack breaks one, blocked switch leaves second");resource(mc.player.getMainHandItem(),4950,9984);check(!attack(mc,SECOND).isCanceled(),"held target switch allowed after source delay");mine(mc,SECOND);release(mc);next();}
            case 4->{if(elapsed<25)return;check(mc.level.getBlockState(SECOND).isAir(),"second actual C2S attack removed block");resource(mc.player.getMainHandItem(),4900,9968);done=false;server(mc,p->{var s=p.getMainHandItem();var r=(net.minecraft.world.item.crafting.SmithingRecipe)p.serverLevel().getRecipeManager().byKey(new net.minecraft.resources.ResourceLocation("jdte","time_multitool_hammer")).orElseThrow();var inv=new SimpleContainer(ItemStack.EMPTY,s,new ItemStack(Ability.HAMMER.getUpgradeItem()));check(r.matches(inv,p.level()),"controlled real native smithing recipe setup");var out=r.assemble(inv,p.level().registryAccess());check(ToggleableTool.hasUpgrade(out,Ability.HAMMER),"native ability installed preserving item");p.setItemInHand(InteractionHand.MAIN_HAND,out);p.inventoryMenu.broadcastChanges();done=true;});next();}
            case 5->{if(!done||elapsed<25)return;check(ToggleableTool.hasUpgrade(mc.player.getMainHandItem(),Ability.HAMMER),"actual client receives native upgrade NBT");shift(mc,true);mc.gameMode.useItemOn(mc.player,InteractionHand.MAIN_HAND,new BlockHitResult(Vec3.atCenterOf(THIRD),Direction.WEST,THIRD,false));shift(mc,false);next();}
            case 6->{if(elapsed<25)return;check(mc.screen instanceof com.direwolf20.justdirethings.client.screens.ToolSettingScreen,"actual sneak-block C2S opens registered native settings screen: "+mc.screen);resource(mc.player.getMainHandItem(),4900,9968);var nativeScreen=(com.direwolf20.justdirethings.client.screens.ToolSettingScreen)mc.screen;
                int[] sizes={7,3,3,5,7};boolean[] enabled={true,false,true,true,true};
                check(ToggleableTool.getToolValue(mc.player.getMainHandItem(),"hammer")==sizes[guiPhase]&&ToggleableTool.getSetting(mc.player.getMainHandItem(),"hammer")==enabled[guiPhase],"native GUI source7/off/3/5/7 cycle sync at phase "+guiPhase+", actual="+ToggleableTool.getToolValue(mc.player.getMainHandItem(),"hammer")+"/"+ToggleableTool.getSetting(mc.player.getMainHandItem(),"hammer"));
                if(guiPhase<4){check(nativeScreen.mouseClicked(nativeScreen.getGuiLeft()+6,nativeScreen.getGuiTop()+26,0),"actual native hammer cycle GUI click accepted");guiPhase++;at=ticks;return;}
                shot(mc,"jdte-multitool-native-settings.png");mc.player.closeContainer();var f=com.jdte.common.jei.JDTEJeiPlugin.class.getDeclaredField("runtime");f.setAccessible(true);var jei=(mezz.jei.api.runtime.IJeiRuntime)f.get(null);check(jei!=null,"actual JEI runtime");var recipes=jei.getRecipeManager().createRecipeLookup(mezz.jei.api.constants.RecipeTypes.CRAFTING).get().filter(r->r.getId().equals(new net.minecraft.resources.ResourceLocation("jdte","time_multitool"))).toList();check(recipes.size()==1,"source plain crafting recipe reaches actual JEI");long abilities=mc.level.getRecipeManager().getAllRecipesFor(net.minecraft.world.item.crafting.RecipeType.SMITHING).stream().filter(r->r.getId().getNamespace().equals("jdte")&&r.getId().getPath().startsWith("time_multitool_")).count();check(abilities==10,"all ten native smithing recipes decode on client");jei.getRecipesGui().showRecipes(jei.getRecipeManager().getRecipeCategory(mezz.jei.api.constants.RecipeTypes.CRAFTING),recipes,java.util.List.of());next();}
            case 7->{if(elapsed<25)return;shot(mc,"jdte-multitool-jei.png");mc.screen.onClose();mc.player.closeContainer();done=false;server(mc,p->{expected=new net.minecraft.nbt.CompoundTag();expected.put("tool",p.getMainHandItem().save(new net.minecraft.nbt.CompoundTag()));expected.put("inventory",p.getInventory().save(new net.minecraft.nbt.ListTag()));try{net.minecraft.nbt.NbtIo.writeCompressed(expected,mc.gameDirectory.toPath().resolve("multitool-client-expected.nbt").toFile());}catch(java.io.IOException x){throw new IllegalStateException(x);}done=true;});next();}
            case 8->{if(!done||elapsed<30)return;stage=20;at=ticks;disconnecting=true;try{mc.level.disconnect();mc.clearLevel();mc.setScreen(new net.minecraft.client.gui.screens.TitleScreen());}finally{disconnecting=false;}}
            case 21->{if(mc.player.tickCount<70)return;done=false;server(mc,p->{check(expected.getCompound("tool").equals(p.getMainHandItem().save(new net.minecraft.nbt.CompoundTag()))&&expected.getList("inventory",10).equals(p.getInventory().save(new net.minecraft.nbt.ListTag())),"actual player save/old server stop/new integrated server/rejoin exact whole inventory and item NBT");done=true;});check(TimeMultitoolItem.getSelectedSpeedMode(mc.player.getMainHandItem())==TimeMultitoolSpeedMode.SIXTEEN&&ToggleableTool.hasUpgrade(mc.player.getMainHandItem(),Ability.HAMMER),"mode16 and native ability client-restored");resource(mc.player.getMainHandItem(),4900,9968);shot(mc,"jdte-multitool-reconnected.png");shift(mc,true);mc.gameMode.useItem(mc.player,InteractionHand.MAIN_HAND);shift(mc,false);next();}
            case 22->{if(!done||elapsed<25)return;check(TimeMultitoolItem.getSelectedSpeedMode(mc.player.getMainHandItem())==TimeMultitoolSpeedMode.TWO_FIFTY_SIX,"post-rejoin actual mode256 C2S");mine(mc,THIRD);next();}
            case 23->{if(elapsed<30)return;check(mc.level.getBlockState(THIRD).isAir(),"resumed real client mining");resource(mc.player.getMainHandItem(),4850,9712);shot(mc,"jdte-multitool-resumed.png");Files.writeString(mc.gameDirectory.toPath().resolve("multitool-smoke-success.txt"),"PASS: real graphical client/server C2S sneak-air1/2/4/16 and restored256 modes, actual Forge input press/target switch gate+controller mining, exact50FE/16mB per first two removed blocks; native ability recipe fixture and real native settings button7/off/3/5/7 C2S+NBT synchronization, real JEI source crafting/all10 client-decoded smithing recipes, screenshots; actual player disconnect/save/new integrated server/rejoin exact whole inventory/FE/fluid/mode/native-ability/name/unknown NBT then actual256x mining resumes4850FE/9712mB. Material/recipe setup controlled; input events generated, real packet controller honored cancellation; not physical human input, independent multiplayer or GUI smithing claim.\n");mc.stop();stage=24;}
        }
    }
}
